double sum = 0.0;
double lcg_a = 1103515245u;  // LCG multiplier (common value)
double c = 12345u;           // LCG increment
double m = 2147483648u;      // LCG modulus (2^31)

for (int i = 0; i < n_points; i++) {
    // Generate uniform random number in [0, 1) using LCG
    seed = (static_cast<unsigned long long>(lcg_a) * seed + c) % static_cast<unsigned long long>(m);
    double u = static_cast<double>(seed) / static_cast<double>(m);

    // Transform to uniform in [a, b]
    double x = a + (b - a) * u;

    // Evaluate function and accumulate
    sum += f(x);
}

// Return integral estimate using mean value method
return (std::fabs(b - a) * sum) / static_cast<double>(n_points);

